BY_ID = {q["id"]: q for q in BANK}


def pick_question(topic: str, difficulty: int, exclude: set[str], kind: str | None = None,
                  rng: random.Random | None = None) -> Q | None:
    """Nearest-difficulty unused question for a topic (optionally of a given kind)."""
    rng = rng or random.Random(0)
    pool = [q for q in BANK if q["topic"] == topic and q["id"] not in exclude and (kind is None or q["kind"] == kind)]
    if not pool:
        return None
    best = min(abs(q["difficulty"] - difficulty) for q in pool)
    return rng.choice([q for q in pool if abs(q["difficulty"] - difficulty) == best])


def generate_question(topic: str, difficulty: int, context: str, llm: LLM, kind: str = "concept") -> Q | None:
    """LLM mode: a fresh question grounded in the target job description / recent reading."""
    if not (llm and llm.available):
        return None
    system = "You are a senior interviewer for AI-engineering internships. You write precise, fair questions with gradeable rubrics."
    prompt = f"""Write one {kind} interview question on "{label(topic)}" at difficulty {difficulty}/3,
grounded in this context (job description excerpt or article the candidate read):
<<<
{context[:3000]}
>>>
Return JSON: {{"prompt": str, "key_points": [[str, ...], ...] (3-6 points, each a list of short lowercase phrases that would show the point is covered),
"model_answer": str, "follow_up": {{"prompt": str, "key_points": [[str, ...], ...]}}}}"""
    data = llm.complete_json(system, prompt)
    if not data or "prompt" not in data or "key_points" not in data:
        return None
    return {"id": f"gen-{topic}-{abs(hash(data['prompt'])) % 10**6}", "topic": topic, "kind": kind,
            "difficulty": difficulty, "prompt": data["prompt"], "key_points": data["key_points"],
            "model_answer": data.get("model_answer", ""), "follow_up": data.get("follow_up"),
            "resources": [], "generated": True}


